arguments.command:
cat > /tmp/fetch_wiki.py <<'PY'
import json, subprocess, sys, urllib.parse, re

def get(title):
    url='https://en.wikipedia.org/w/api.php?action=query&prop=revisions&titles='+urllib.parse.quote(title.replace(' ','_'))+'&rvprop=content&format=json&formatversion=2'
    out=subprocess.check_output(['bash','-lc', f"curl -L -A 'Mozilla/5.0' -s '{url}'"], text=True)
    j=json.loads(out)
    return j['query']['pages'][0]['revisions'][0]['content']
for t in sys.argv[1:]:
    print('===',t)
    txt=get(t)
    for key in ['crew_members','crew_size','launch_date','launch_site','landing_date','landing_site','mission_duration','spacecraft','mission_type']:
        m=re.search(r'\|\s*'+re.escape(key)+r'\s*=\s*(.*)', txt)
        if m: print(key, '=>', m.group(1)[:200])
    for pat in ['backup', 'prime crew', 'backup crew']:
        if pat in txt.lower():
            print('has',pat)
    print(txt[:2500])
PY
python3 /tmp/fetch_wiki.py 'Gemini 3' 'Apollo 7' 'Mercury-Atlas 6' 'Skylab 2' | sed -n '1,220p'

python3 - <<'PY'
import subprocess, json, urllib.parse, re

def get(title):
    url='https://en.wikipedia.org/w/api.php?action=query&prop=revisions&titles='+urllib.parse.quote(title.replace(' ','_'))+'&rvprop=content&format=json&formatversion=2'
    out=subprocess.check_output(['bash','-lc', f"curl -L -A 'Mozilla/5.0' -s '{url}'"], text=True)
    return json.loads(out)['query']['pages'][0]['revisions'][0]['content']
for t in ['Gemini 3','Apollo 11','Apollo 13','Skylab 4','Mercury-Atlas 6']:
    txt=get(t)
    for pat in [r'backup crew[^\n]{0,400}', r'prime crew[^\n]{0,400}', r'backup[^\n]{0,400}']:
        m=re.search(pat, txt, re.I)
        if m:
            print('\n==',t,pat,'\n',m.group(0)[:500])
PY

